steps.solutionCode:
const button = document.querySelector('.card__pick');
const picked = document.querySelector('#picked');

button.addEventListener('click', () => {
  picked.textContent = '1개 담김';
});

button.click();

const picked = document.querySelector('#picked');

let count = 0;

for (const button of document.querySelectorAll('.card__pick')) {
  button.addEventListener('click', () => {
    count = count + 1;
    picked.textContent = `${count}개 담김`;
  });
}
